class Fila:
    def __init__(self, itens=None):
        self.itens = itens or []

    def __len__(self):
        return len(self.itens)

    def __iter__(self):
        return iter(self.itens)

    def __bool__(self):
        return bool(self.itens)

filas = Fila([1, 2])
print(len(filas))
print(bool(filas))

